package com.github.diogogdias.discordlootboxer;

enum AccountType
{
	IRONMAN("Ironman"),
	HARDCORE_IRONMAN("Hardcore Ironman"),
	ULTIMATE_IRONMAN("Ultimate Ironman"),
	GROUP_IRONMAN("Group Ironman"),
	HARDCORE_GROUP_IRONMAN("Hardcore Group Ironman"),
	UNRANKED_GROUP_IRONMAN("Unranked Group Ironman");

	private final String label;

	AccountType(String label)
	{
		this.label = label;
	}

	String label()
	{
		return label;
	}
}

package com.github.diogogdias.discordlootboxer;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.hiscore.HiscoreClient;
import net.runelite.client.hiscore.HiscoreEndpoint;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.util.Text;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

@Slf4j
@Singleton
class AccountTypeResolver
{
	private static final String CONFIG_GROUP = "discordlootboxer";
	private static final String SEEN_PREFIX = "seen_";

	private final HiscoreClient hiscoreClient;
	private final OkHttpClient httpClient;
	private final Gson gson;
	private final ConfigManager configManager;

	// name (lowercase, sanitized) -> type seen in public chat this session
	private final Map<String, AccountType> chatIconCache = new ConcurrentHashMap<>();
	// probe results cached per session; outcomes including unknown are cached once a probe
	// completes, timeouts are not cached
	private final Map<String, Optional<AccountType>> probeCache = new ConcurrentHashMap<>();

	@Inject
	AccountTypeResolver(HiscoreClient hiscoreClient, OkHttpClient httpClient, Gson gson, ConfigManager configManager)
	{
		this.hiscoreClient = hiscoreClient;
		this.httpClient = httpClient;
		this.gson = gson;
		this.configManager = configManager;
	}

	/**
	 * Records an account type sighting from any icon-prefixed player name:
	 * chat sender names and menu entry targets (the game embeds the icon in
	 * both). Menu targets may carry a trailing combat level, hence
	 * removeLevels.
	 */
	void onPlayerNameWithIcon(String rawName)
	{
		AccountType type = AccountTypes.fromChatName(rawName);
		if (type == null)
		{
			return;
		}
		// Menu targets carry a trailing combat level, e.g. "Name  (level-126)"
		String cleaned = Text.removeTags(rawName).replaceFirst("\\s*\\(level-\\d+\\)\\s*$", "");
		String k = key(cleaned);
		if (type.equals(chatIconCache.put(k, type)))
		{
			// Already recorded; skip the config write (menu entries fire per hover)
			return;
		}
		// Persist sightings: chat icons are the only reliable GIM source,
		// so once seen a player stays identified across sessions
		configManager.setConfiguration(CONFIG_GROUP, seenKey(k), type.name());
	}

	/**
	 * Resolves the account type: chat-icon cache first (session, then
	 * persisted sightings), then hiscore probing with Wise Old Man
	 * exp-comparison logic plus a TempleOSRS GIM flag check. Completes with
	 * null when unknown. Never completes exceptionally.
	 */
	CompletableFuture<AccountType> resolve(String playerName)
	{
		String k = key(playerName);
		AccountType seen = chatIconCache.get(k);
		if (seen != null)
		{
			return CompletableFuture.completedFuture(seen);
		}
		AccountType persisted = persistedSighting(k);
		if (persisted != null)
		{
			return CompletableFuture.completedFuture(persisted);
		}
		Optional<AccountType> probed = probeCache.get(k);
		if (probed != null)
		{
			return CompletableFuture.completedFuture(probed.orElse(null));
		}

		CompletableFuture<Long> regular = overallExp(playerName, HiscoreEndpoint.NORMAL);
		CompletableFuture<Long> iron = overallExp(playerName, HiscoreEndpoint.IRONMAN);
		CompletableFuture<Long> hc = overallExp(playerName, HiscoreEndpoint.HARDCORE_IRONMAN);
		CompletableFuture<Long> uim = overallExp(playerName, HiscoreEndpoint.ULTIMATE_IRONMAN);
		CompletableFuture<Boolean> gim = templeGimFlag(playerName);

		return CompletableFuture.allOf(regular, iron, hc, uim, gim)
			.thenApply(v ->
			{
				AccountType t = AccountTypes.decide(regular.join(), iron.join(), hc.join(), uim.join());
				if (t == null && Boolean.TRUE.equals(gim.join()))
				{
					// Invisible on per-player hiscores but flagged as a group
					// ironman on TempleOSRS
					t = AccountType.GROUP_IRONMAN;
				}
				probeCache.put(k, Optional.ofNullable(t));
				return t;
			})
			.orTimeout(2, TimeUnit.SECONDS)
			.exceptionally(e ->
			{
				log.debug("account type probe failed for {}", playerName, e);
				return null;
			});
	}

	private AccountType persistedSighting(String k)
	{
		String stored = configManager.getConfiguration(CONFIG_GROUP, seenKey(k));
		if (stored == null || stored.isEmpty())
		{
			return null;
		}
		try
		{
			AccountType type = AccountType.valueOf(stored);
			chatIconCache.put(k, type);
			return type;
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	private CompletableFuture<Long> overallExp(String playerName, HiscoreEndpoint endpoint)
	{
		return hiscoreClient.lookupAsync(playerName, endpoint)
			.<Long>thenApply(r -> r == null ? null : exp(r))
			.exceptionally(e -> null);
	}

	/**
	 * TempleOSRS knows the GIM status of players tracked there. Best effort:
	 * completes false on any failure or when the player is untracked.
	 */
	private CompletableFuture<Boolean> templeGimFlag(String playerName)
	{
		CompletableFuture<Boolean> future = new CompletableFuture<>();
		HttpUrl url = HttpUrl.parse("https://templeosrs.com/api/player_info.php").newBuilder()
			.addQueryParameter("player", playerName.replace(' ', ' '))
			.build();
		httpClient.newCall(new Request.Builder().url(url).build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				future.complete(false);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					JsonObject json = gson.fromJson(r.body().string(), JsonObject.class);
					JsonObject data = json.getAsJsonObject("data");
					future.complete(data != null && data.has("GIM") && data.get("GIM").getAsInt() != 0);
				}
				catch (Exception e)
				{
					future.complete(false);
				}
			}
		});
		return future;
	}

	private static Long exp(HiscoreResult result)
	{
		net.runelite.client.hiscore.Skill overall = result.getSkill(HiscoreSkill.OVERALL);
		return overall == null ? null : overall.getExperience();
	}

	private static String seenKey(String k)
	{
		return SEEN_PREFIX + k.replace(' ', '_');
	}

	private static String key(String name)
	{
		// NBSP appears in place of spaces in some client name strings
		return name.replace(' ', ' ').trim().toLowerCase();
	}
}

package com.github.diogogdias.discordlootboxer;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class AccountTypes
{
	private static final Pattern ICON = Pattern.compile("<img=(\\d+)>");

	private AccountTypes()
	{
	}

	static AccountType fromChatName(String rawName)
	{
		if (rawName == null)
		{
			return null;
		}
		// A name can carry several icons (e.g. a skull before the account
		// badge on PvP targets); scan them all for the first recognized one
		Matcher m = ICON.matcher(rawName);
		while (m.find())
		{
			switch (Integer.parseInt(m.group(1)))
			{
				case 2: return AccountType.IRONMAN;
				case 3: return AccountType.ULTIMATE_IRONMAN;
				case 10: return AccountType.HARDCORE_IRONMAN;
				case 41: return AccountType.GROUP_IRONMAN;
				case 42: return AccountType.HARDCORE_GROUP_IRONMAN;
				case 43: return AccountType.UNRANKED_GROUP_IRONMAN;
				default: break;
			}
		}
		return null;
	}

	/**
	 * Wise Old Man's AssertPlayerTypeService logic. A null argument means the
	 * player is absent from that hiscore endpoint. Returns null for unknown
	 * (main or GIM, indistinguishable by hiscores).
	 */
	static AccountType decide(Long regularExp, Long ironExp, Long hcExp, Long uimExp)
	{
		if (ironExp == null)
		{
			return null;
		}
		if (regularExp != null && regularExp > ironExp)
		{
			// De-ironed: main stats diverged above the frozen ironman entry
			return null;
		}
		if (hcExp != null && hcExp >= ironExp)
		{
			return AccountType.HARDCORE_IRONMAN;
		}
		if (uimExp != null && uimExp >= ironExp)
		{
			return AccountType.ULTIMATE_IRONMAN;
		}
		return AccountType.IRONMAN;
	}
}

package com.github.diogogdias.discordlootboxer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("discordlootboxer")
public interface DiscordLootBoxerConfig extends Config
{
	@ConfigSection(
		name = "Webhooks",
		description = "Where messages are sent",
		position = 0
	)
	String webhooksSection = "webhooks";

	@ConfigSection(
		name = "PK kills",
		description = "Settings for player kill notifications",
		position = 1
	)
	String pkSection = "pk";

	@ConfigSection(
		name = "Big loot",
		description = "Settings for valuable loot notifications",
		position = 2
	)
	String lootSection = "loot";

	@ConfigItem(
		keyName = "webhookUrl",
		name = "Webhook URL",
		description = "Discord webhook URL to send messages to",
		position = 0,
		section = webhooksSection
	)
	default String webhookUrl()
	{
		return "";
	}

	@ConfigItem(
		keyName = "pkWebhookUrl",
		name = "PK webhook override",
		description = "Optional webhook URL used only for PK messages; empty falls back to the main Webhook URL",
		position = 1,
		section = webhooksSection
	)
	default String pkWebhookUrl()
	{
		return "";
	}

	@ConfigItem(
		keyName = "lootWebhookUrl",
		name = "Loot webhook override",
		description = "Optional webhook URL used only for loot messages; empty falls back to the main Webhook URL",
		position = 2,
		section = webhooksSection
	)
	default String lootWebhookUrl()
	{
		return "";
	}

	@ConfigItem(
		keyName = "notifyPk",
		name = "PK notifications",
		description = "Send a message when you kill another player",
		position = 0,
		section = pkSection
	)
	default boolean notifyPk()
	{
		return true;
	}

	@ConfigItem(
		keyName = "funnyMessages",
		name = "Funny messages",
		description = "Random verbs and quips on kill messages, like 'slew' and 'he stood no chance'",
		position = 1,
		section = pkSection
	)
	default boolean funnyMessages()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notifyLoot",
		name = "Big loot notifications",
		description = "Send a message when you receive valuable loot",
		position = 0,
		section = lootSection
	)
	default boolean notifyLoot()
	{
		return true;
	}

	@ConfigItem(
		keyName = "minLootValue",
		name = "Min loot value",
		description = "Minimum GE value in coins for a loot notification",
		position = 1,
		section = lootSection
	)
	default int minLootValue()
	{
		return 1_000_000;
	}
}

package com.github.diogogdias.discordlootboxer;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;

@Slf4j
@PluginDescriptor(
	name = "Discord Loot Boxer",
	description = "Sends clean screenshot-first Discord messages for PK kills and big loot drops",
	tags = {"discord", "webhook", "pk", "loot", "screenshot", "wilderness"}
)
public class DiscordLootBoxerPlugin extends Plugin
{
	@Inject
	private PkNotifier pkNotifier;

	@Inject
	private LootNotifier lootNotifier;

	@Inject
	private AccountTypeResolver accountTypes;

	@Provides
	DiscordLootBoxerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DiscordLootBoxerConfig.class);
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		pkNotifier.onHitsplatApplied(event);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		pkNotifier.onGameTick();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		pkNotifier.onChatMessage(event);
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		lootNotifier.onLootReceived(event);
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		// The game embeds the account icon in menu targets for player options
		// (Attack, Trade, Follow...), so hovering a player reveals their type
		String target = event.getTarget();
		if (target != null && target.contains("<img="))
		{
			accountTypes.onPlayerNameWithIcon(target);
		}
	}
}

package com.github.diogogdias.discordlootboxer;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.io.IOException;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

@Slf4j
@Singleton
class DiscordSender
{
	private static final MediaType PNG = MediaType.parse("image/png");
	private static final String SCREENSHOT_NAME = "lootboxer.png";
	private static final String ICON_NAME = "icon.png";
	// Neutral dark strip so the embed blends into Discord's dark theme
	private static final int EMBED_COLOR = 0x2B2D31;

	private final OkHttpClient httpClient;

	@Inject
	DiscordSender(OkHttpClient httpClient)
	{
		this.httpClient = httpClient;
	}

	/**
	 * Minimal embed: one bold author line, an optional small italic flavor
	 * line, an attached icon as a square thumbnail on the right, and the
	 * screenshot full width below. No fields, no footer.
	 */
	static String payloadJson(String text, String flavor, boolean hasIcon, boolean hasImage)
	{
		JsonObject author = new JsonObject();
		author.addProperty("name", text);

		JsonObject embed = new JsonObject();
		embed.add("author", author);
		if (flavor != null && !flavor.isEmpty())
		{
			embed.addProperty("description", "*" + flavor + "*");
		}
		embed.addProperty("color", EMBED_COLOR);
		if (hasIcon)
		{
			JsonObject thumbnail = new JsonObject();
			thumbnail.addProperty("url", "attachment://" + ICON_NAME);
			embed.add("thumbnail", thumbnail);
		}
		if (hasImage)
		{
			JsonObject image = new JsonObject();
			image.addProperty("url", "attachment://" + SCREENSHOT_NAME);
			embed.add("image", image);
		}

		JsonArray embeds = new JsonArray();
		embeds.add(embed);
		JsonObject json = new JsonObject();
		json.add("embeds", embeds);
		return json.toString();
	}

	static String pickUrl(String override, String main)
	{
		String o = override == null ? "" : override.trim();
		if (!o.isEmpty())
		{
			return o;
		}
		return main == null ? "" : main.trim();
	}

	void send(String webhookUrl, String text, String flavor, byte[] screenshotPng, byte[] iconPng)
	{
		String trimmed = webhookUrl == null ? "" : webhookUrl.trim();
		HttpUrl url = HttpUrl.parse(trimmed);
		if (url == null)
		{
			if (!trimmed.isEmpty())
			{
				log.warn("Discord webhook URL is not a valid URL");
			}
			return;
		}

		MultipartBody.Builder body = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("payload_json", payloadJson(text, flavor, iconPng != null, screenshotPng != null));
		int fileIndex = 0;
		if (screenshotPng != null)
		{
			body.addFormDataPart("files[" + fileIndex++ + "]", SCREENSHOT_NAME, RequestBody.create(PNG, screenshotPng));
		}
		if (iconPng != null)
		{
			body.addFormDataPart("files[" + fileIndex + "]", ICON_NAME, RequestBody.create(PNG, iconPng));
		}

		Request request = new Request.Builder().url(url).post(body.build()).build();
		execute(request, true);
	}

	private void execute(Request request, boolean allowRetry)
	{
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				retryOrWarn(request, allowRetry, e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (!r.isSuccessful())
					{
						retryOrWarn(request, allowRetry, "HTTP " + r.code());
					}
				}
			}
		});
	}

	private void retryOrWarn(Request request, boolean allowRetry, String reason)
	{
		if (allowRetry)
		{
			execute(request, false);
		}
		else
		{
			log.warn("Discord webhook delivery failed: {}", reason);
		}
	}
}

package com.github.diogogdias.discordlootboxer;

import java.util.List;

final class LootDecision
{
	static final class Stack
	{
		final int itemId;
		final int quantity;
		final long unitPrice;

		Stack(int itemId, int quantity, long unitPrice)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.unitPrice = unitPrice;
		}
	}

	static final class Notable
	{
		final int itemId;
		final int quantity;
		final long itemValue;
		final long totalValue;
		final boolean totalTriggered;

		Notable(int itemId, int quantity, long itemValue, long totalValue, boolean totalTriggered)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.itemValue = itemValue;
			this.totalValue = totalValue;
			this.totalTriggered = totalTriggered;
		}
	}

	private LootDecision()
	{
	}

	/**
	 * Single item unit price at or over minValue always triggers. Total
	 * value only triggers for the Loot Chest (Dink's special case), so a
	 * pile of cheap PvM loot never spams.
	 */
	static Notable evaluate(List<Stack> stacks, boolean isLootChest, long minValue)
	{
		Stack best = null;
		long bestUnitPrice = -1;
		long total = 0;
		for (Stack s : stacks)
		{
			long stackValue = s.unitPrice * s.quantity;
			total += stackValue;
			if (s.unitPrice > bestUnitPrice)
			{
				bestUnitPrice = s.unitPrice;
				best = s;
			}
		}
		if (best == null)
		{
			return null;
		}
		long bestStackValue = best.unitPrice * best.quantity;
		if (bestUnitPrice >= minValue)
		{
			return new Notable(best.itemId, best.quantity, bestStackValue, total, false);
		}
		if (isLootChest && total >= minValue)
		{
			return new Notable(best.itemId, best.quantity, bestStackValue, total, true);
		}
		return null;
	}
}

package com.github.diogogdias.discordlootboxer;

import java.util.OptionalLong;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class LootKeyParser
{
	// Fallback wording: any line mentioning "loot key" with a 4+ digit value.
	// The 4-digit floor keeps the 5-key limit message from matching.
	private static final Pattern VALUE = Pattern.compile("(?i)loot key[^0-9]*([0-9][0-9,]{3,})");

	// Verified live wording (clan broadcast channel):
	// "Don Bate has defeated IrViMax and received (9,535 coins) worth of loot!"
	private static final Pattern CLAN_KILL = Pattern.compile(
		"(?i)^(.+?) has defeated (.+?) and received \\(([0-9][0-9,]*) coins?\\) worth of loot!?$");

	static final class ClanKill
	{
		final String killer;
		final String victim;
		final long value;

		ClanKill(String killer, String victim, long value)
		{
			this.killer = killer;
			this.victim = victim;
			this.value = value;
		}
	}

	private LootKeyParser()
	{
	}

	/**
	 * Parses the clan broadcast kill message; null when the line is anything
	 * else. Caller must verify the killer is the local player.
	 */
	static ClanKill parseClanKill(String chatLine)
	{
		if (chatLine == null)
		{
			return null;
		}
		Matcher m = CLAN_KILL.matcher(chatLine.trim());
		if (!m.matches())
		{
			return null;
		}
		try
		{
			return new ClanKill(m.group(1).trim(), m.group(2).trim(),
				Long.parseLong(m.group(3).replace(",", "")));
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	static OptionalLong parseValue(String chatLine)
	{
		if (chatLine == null)
		{
			return OptionalLong.empty();
		}
		Matcher m = VALUE.matcher(chatLine);
		if (!m.find())
		{
			return OptionalLong.empty();
		}
		try
		{
			return OptionalLong.of(Long.parseLong(m.group(1).replace(",", "")));
		}
		catch (NumberFormatException e)
		{
			return OptionalLong.empty();
		}
	}
}

package com.github.diogogdias.discordlootboxer;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

@Slf4j
@Singleton
class LootNotifier
{
	private static final int COINS_ITEM_ID = 995;

	private final Client client;
	private final ItemManager itemManager;
	private final DiscordLootBoxerConfig config;
	private final DiscordSender sender;
	private final ScreenshotUtil screenshots;

	@Inject
	LootNotifier(Client client, ItemManager itemManager, DiscordLootBoxerConfig config,
		DiscordSender sender, ScreenshotUtil screenshots)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.config = config;
		this.sender = sender;
		this.screenshots = screenshots;
	}

	/**
	 * Encodes the item's sprite as an upscaled PNG once the client has
	 * loaded it; completes with null on failure or after 2 seconds.
	 */
	private java.util.concurrent.CompletableFuture<byte[]> itemIconPng(int itemId)
	{
		java.util.concurrent.CompletableFuture<byte[]> future = new java.util.concurrent.CompletableFuture<>();
		net.runelite.client.util.AsyncBufferedImage img = itemManager.getImage(itemId);
		img.onLoaded(() ->
		{
			try
			{
				future.complete(ScreenshotUtil.upscaledIconPng(img));
			}
			catch (Exception e)
			{
				future.complete(null);
			}
		});
		return future.completeOnTimeout(null, 2, java.util.concurrent.TimeUnit.SECONDS);
	}

	void onLootReceived(LootReceived event)
	{
		if (event.getType() == LootRecordType.PLAYER)
		{
			// PK kills are reported by PkNotifier; ground loot from a keyless kill
			// would double-report, so player loot records are skipped (Dink's default)
			return;
		}

		String url = DiscordSender.pickUrl(config.lootWebhookUrl(), config.webhookUrl());
		if (!config.notifyLoot() || url.isEmpty() || client.getLocalPlayer() == null)
		{
			return;
		}

		String source = event.getName() == null ? "Unknown" : event.getName();
		boolean isLootChest = "Loot Chest".equalsIgnoreCase(source);

		List<LootDecision.Stack> stacks = new ArrayList<>();
		for (ItemStack item : event.getItems())
		{
			stacks.add(new LootDecision.Stack(item.getId(), item.getQuantity(), itemManager.getItemPrice(item.getId())));
		}

		LootDecision.Notable notable = LootDecision.evaluate(stacks, isLootChest, config.minLootValue());
		if (notable == null)
		{
			return;
		}

		String local = client.getLocalPlayer().getName();
		String message;
		int iconItemId;
		if (notable.totalTriggered)
		{
			message = local + " received " + ValueFormat.kmb(notable.totalValue)
				+ " coins in loot from Loot Chest";
			iconItemId = COINS_ITEM_ID;
		}
		else
		{
			String itemName = itemManager.getItemComposition(notable.itemId).getName();
			message = local + " received " + itemName + " ("
				+ ValueFormat.kmb(notable.itemValue) + ") from " + source;
			iconItemId = notable.itemId;
		}

		// Item sprite as the embed thumbnail, upscaled nearest neighbor
		itemIconPng(iconItemId).thenCombine(screenshots.capture(), (icon, png) ->
		{
			sender.send(url, message, null, png, icon);
			return null;
		});
	}
}

package com.github.diogogdias.discordlootboxer;

import java.util.concurrent.ThreadLocalRandom;

final class PkMessage
{
	// Package-private for tests
	static final String[] VERBS = {
		"killed", "slew", "smoked", "flattened", "deleted", "clapped", "farmed", "bonked"
	};

	static final String[] QUIPS = {
		"he stood no chance",
		"wtf was he thinking",
		"another one bites the dust",
		"didn't even fight back",
		"free loot",
		"ez clap",
		"sit rat",
		"straight to Lumbridge",
		"should have kept his anglerfish down",
		"gg go next"
	};

	private PkMessage()
	{
	}

	/**
	 * One plain line for the embed author (Discord renders it bold):
	 * "Don Bate slew IrViMax (126) for 4,432 coins".
	 * The value part is omitted when unknown; the account type shows as the
	 * embed thumbnail, not as text.
	 */
	static String build(String localName, String victimName, int combatLevel, String verb, Long keyValue)
	{
		StringBuilder sb = new StringBuilder();
		sb.append(localName).append(' ').append(verb).append(' ').append(victimName)
			.append(" (").append(combatLevel).append(')');
		if (keyValue != null)
		{
			sb.append(" for ").append(String.format(java.util.Locale.ROOT, "%,d", keyValue)).append(" coins");
		}
		return sb.toString();
	}

	static String randomVerb()
	{
		return VERBS[ThreadLocalRandom.current().nextInt(VERBS.length)];
	}

	static String randomQuip()
	{
		return QUIPS[ThreadLocalRandom.current().nextInt(QUIPS.length)];
	}
}

package com.github.diogogdias.discordlootboxer;

import java.util.Map;
import java.util.OptionalLong;
import java.util.WeakHashMap;
import java.util.concurrent.CompletableFuture;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.client.util.Text;

@Slf4j
@Singleton
class PkNotifier
{
	// Hold window: PvP death animation plus the clan loot broadcast lag several
	// seconds behind isDead() (observed 5s live), so allow up to 15 ticks (9s).
	// Dispatch still fires early the moment the value and account type resolve.
	private static final int MAX_HOLD_TICKS = 15;

	private final Client client;
	private final DiscordLootBoxerConfig config;
	private final DiscordSender sender;
	private final ScreenshotUtil screenshots;
	private final AccountTypeResolver accountTypes;

	// Damage dealt by the local player recently, per target
	private final Map<Player, Integer> attacked = new WeakHashMap<>(4);

	private PendingKill pending;

	// Buffer for loot value that arrives before handleKill (same-tick race)
	private Long recentKeyValue;
	private String recentKeyVictim;
	private int recentKeyTick;

	private static final class PendingKill
	{
		final String victimName;
		final int combatLevel;
		final String localName;
		final CompletableFuture<byte[]> screenshot;
		final CompletableFuture<AccountType> accountType;
		Long keyValue;
		// Starts at -1 because the creation tick onGameTick pass increments it to 0;
		// timeout then fires MAX_HOLD_TICKS full ticks after the kill.
		int ticksHeld = -1;
		boolean sent;

		PendingKill(String victimName, int combatLevel, String localName,
			CompletableFuture<byte[]> screenshot, CompletableFuture<AccountType> accountType)
		{
			this.victimName = victimName;
			this.combatLevel = combatLevel;
			this.localName = localName;
			this.screenshot = screenshot;
			this.accountType = accountType;
		}
	}

	@Inject
	PkNotifier(Client client, DiscordLootBoxerConfig config, DiscordSender sender,
		ScreenshotUtil screenshots, AccountTypeResolver accountTypes)
	{
		this.client = client;
		this.config = config;
		this.sender = sender;
		this.screenshots = screenshots;
		this.accountTypes = accountTypes;
	}

	void onHitsplatApplied(HitsplatApplied event)
	{
		if (!config.notifyPk())
		{
			return;
		}
		Hitsplat hit = event.getHitsplat();
		if (hit.getAmount() <= 0 || !hit.isMine())
		{
			return;
		}
		if (!(event.getActor() instanceof Player) || event.getActor() == client.getLocalPlayer())
		{
			return;
		}
		attacked.merge((Player) event.getActor(), hit.getAmount(), Integer::sum);
	}

	void onGameTick()
	{
		if (!attacked.isEmpty())
		{
			for (Player target : attacked.keySet())
			{
				if (target.isDead())
				{
					handleKill(target);
					break;
				}
			}
			attacked.clear();
		}

		if (pending != null && !pending.sent)
		{
			pending.ticksHeld++;
			boolean complete = pending.keyValue != null && pending.accountType.isDone();
			if (complete || pending.ticksHeld >= MAX_HOLD_TICKS)
			{
				dispatch(pending);
			}
		}
	}

	void onChatMessage(ChatMessage event)
	{
		switch (event.getType())
		{
			// All of these render the sender name with the account icon
			case PUBLICCHAT:
			case MODCHAT:
			case FRIENDSCHAT:
			case CLAN_CHAT:
			case CLAN_GUEST_CHAT:
			case PRIVATECHAT:
			case MODPRIVATECHAT:
			case TRADEREQ:
			case CHALREQ_TRADE:
			case CHALREQ_FRIENDSCHAT:
			case CHALREQ_CLANCHAT:
				accountTypes.onPlayerNameWithIcon(event.getName());
				return;
			default:
				break;
		}
		// Loot key value arrives on the clan broadcast channel, not as a game message
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM
			&& event.getType() != ChatMessageType.CLAN_MESSAGE)
		{
			return;
		}
		String line = Text.removeTags(event.getMessage());

		// Primary source: the clan broadcast
		// "<killer> has defeated <victim> and received (9,535 coins) worth of loot!"
		LootKeyParser.ClanKill clanKill = LootKeyParser.parseClanKill(line);
		if (clanKill != null)
		{
			Player local = client.getLocalPlayer();
			if (local == null || !namesMatch(local.getName(), clanKill.killer))
			{
				// A clanmate's kill, not ours
				return;
			}
			if (pending != null && !pending.sent && namesMatch(pending.victimName, clanKill.victim))
			{
				pending.keyValue = clanKill.value;
			}
			else
			{
				// Buffer it for the next kill (same-tick race before handleKill)
				recentKeyValue = clanKill.value;
				recentKeyVictim = clanKill.victim;
				recentKeyTick = client.getTickCount();
			}
			return;
		}

		// Secondary: any wording that mentions a loot key with a value
		OptionalLong value = LootKeyParser.parseValue(line);
		if (value.isPresent())
		{
			if (pending != null && !pending.sent)
			{
				pending.keyValue = value.getAsLong();
			}
			else
			{
				recentKeyValue = value.getAsLong();
				recentKeyVictim = null;
				recentKeyTick = client.getTickCount();
			}
		}
		else if (line.toLowerCase().contains("loot key"))
		{
			log.debug("unmatched loot key line: {}", line);
		}
		else if (pending != null && !pending.sent)
		{
			// Diagnostic: capture game messages during the hold window so any
			// other value wording can be identified from the log
			log.debug("chat during hold: {}", line);
		}
	}

	private static boolean namesMatch(String a, String b)
	{
		if (a == null || b == null)
		{
			return false;
		}
		return a.replace(' ', ' ').trim().equalsIgnoreCase(b.replace(' ', ' ').trim());
	}

	private void handleKill(Player target)
	{
		if (DiscordSender.pickUrl(config.pkWebhookUrl(), config.webhookUrl()).isEmpty()
			|| client.getLocalPlayer() == null || target.getName() == null)
		{
			return;
		}
		// A new kill while one is held: flush the old one immediately
		if (pending != null && !pending.sent)
		{
			dispatch(pending);
		}
		String victim = Text.removeTags(target.getName()).replace(' ', ' ');
		String local = client.getLocalPlayer().getName();
		pending = new PendingKill(
			victim,
			target.getCombatLevel(),
			local,
			screenshots.capture(),
			accountTypes.resolve(victim));
		// Transfer buffered key value if it arrived on the same tick and the
		// victim matches (a victimless buffer comes from the generic wording)
		if (recentKeyValue != null && client.getTickCount() - recentKeyTick <= 2
			&& (recentKeyVictim == null || namesMatch(victim, recentKeyVictim)))
		{
			pending.keyValue = recentKeyValue;
		}
		recentKeyValue = null;
		recentKeyVictim = null;
	}

	private void dispatch(PendingKill kill)
	{
		kill.sent = true;
		String url = DiscordSender.pickUrl(config.pkWebhookUrl(), config.webhookUrl());
		kill.accountType
			.thenCombine(kill.screenshot, (type, png) ->
			{
				boolean funny = config.funnyMessages();
				String verb = funny ? PkMessage.randomVerb() : "killed";
				String flavor = funny ? PkMessage.randomQuip() : null;
				String message = PkMessage.build(kill.localName, kill.victimName, kill.combatLevel, verb, kill.keyValue);
				sender.send(url, message, flavor, png, badgeBytes(type));
				return null;
			})
			.exceptionally(e ->
			{
				log.warn("failed to dispatch PK notification", e);
				return null;
			});
		if (pending == kill)
		{
			pending = null;
		}
	}

	// Lazily loaded, nearest-neighbor upscaled badge PNGs from bundled resources
	private static final Map<String, byte[]> ICON_CACHE = new java.util.concurrent.ConcurrentHashMap<>();

	/**
	 * The account type's actual chat badge, bundled as a resource and
	 * upscaled nearest neighbor so it stays crisp, attached as the embed
	 * thumbnail. Unknown type means a main (or an unseen GIM): they get the
	 * Smelly sock.
	 */
	private static byte[] badgeBytes(AccountType type)
	{
		String name;
		if (type == null)
		{
			name = "Smelly_sock";
		}
		else
		{
			switch (type)
			{
				case IRONMAN: name = "Ironman_chat_badge"; break;
				case HARDCORE_IRONMAN: name = "Hardcore_ironman_chat_badge"; break;
				case ULTIMATE_IRONMAN: name = "Ultimate_ironman_chat_badge"; break;
				case GROUP_IRONMAN: name = "Group_ironman_chat_badge"; break;
				case HARDCORE_GROUP_IRONMAN: name = "Hardcore_group_ironman_chat_badge"; break;
				default: name = "Unranked_group_ironman_chat_badge"; break;
			}
		}
		return ICON_CACHE.computeIfAbsent(name, n ->
		{
			try
			{
				return ScreenshotUtil.upscaledIconPng(
					javax.imageio.ImageIO.read(PkNotifier.class.getResourceAsStream(n + ".png")));
			}
			catch (Exception e)
			{
				log.warn("failed to load badge icon {}", n, e);
				return null;
			}
		});
	}
}

package com.github.diogogdias.discordlootboxer;

import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.DrawManager;

@Slf4j
@Singleton
class ScreenshotUtil
{
	private final DrawManager drawManager;
	private final ScheduledExecutorService executor;

	@Inject
	ScreenshotUtil(DrawManager drawManager, ScheduledExecutorService executor)
	{
		this.drawManager = drawManager;
		this.executor = executor;
	}

	/**
	 * Nearest neighbor integer upscale for tiny pixel-art icons (chat badges,
	 * item sprites) so they stay crisp at Discord thumbnail size.
	 */
	static byte[] upscaledIconPng(BufferedImage src) throws IOException
	{
		int scale = Math.max(1, 96 / Math.max(src.getWidth(), src.getHeight()));
		BufferedImage out = new BufferedImage(src.getWidth() * scale, src.getHeight() * scale, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(java.awt.RenderingHints.KEY_INTERPOLATION, java.awt.RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		g.drawImage(src, 0, 0, out.getWidth(), out.getHeight(), null);
		g.dispose();
		ByteArrayOutputStream stream = new ByteArrayOutputStream();
		ImageIO.write(out, "png", stream);
		return stream.toByteArray();
	}

	static byte[] toPng(Image image) throws IOException
	{
		BufferedImage buffered;
		if (image instanceof BufferedImage)
		{
			buffered = (BufferedImage) image;
		}
		else
		{
			buffered = new BufferedImage(image.getWidth(null), image.getHeight(null), BufferedImage.TYPE_INT_RGB);
			Graphics2D g = buffered.createGraphics();
			g.drawImage(image, 0, 0, null);
			g.dispose();
		}
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		ImageIO.write(buffered, "png", out);
		return out.toByteArray();
	}

	/**
	 * Grabs the next rendered frame at full resolution. Completes with null
	 * on any failure or if no frame arrives within 2 seconds.
	 */
	CompletableFuture<byte[]> capture()
	{
		CompletableFuture<byte[]> future = new CompletableFuture<>();
		drawManager.requestNextFrameListener(frame ->
			executor.execute(() ->
			{
				try
				{
					future.complete(toPng(frame));
				}
				catch (Exception e)
				{
					log.warn("screenshot capture failed", e);
					future.complete(null);
				}
			}));
		executor.schedule(() -> future.complete(null), 2, TimeUnit.SECONDS);
		return future;
	}
}

package com.github.diogogdias.discordlootboxer;

import java.util.Locale;

final class ValueFormat
{
	private ValueFormat()
	{
	}

	static String kmb(long value)
	{
		if (value >= 1_000_000_000L)
		{
			return oneDecimal(value / 1_000_000_000.0) + "B";
		}
		if (value >= 1_000_000L)
		{
			return oneDecimal(value / 1_000_000.0) + "M";
		}
		if (value >= 1_000L)
		{
			return (value / 1_000L) + "K";
		}
		return Long.toString(value);
	}

	private static String oneDecimal(double d)
	{
		String s = String.format(Locale.ROOT, "%.1f", d);
		return s.endsWith(".0") ? s.substring(0, s.length() - 2) : s;
	}
}

