public class AccountTypesTest
{
	@Test
	public void parsesChatIcons()
	{
		assertEquals(AccountType.IRONMAN, AccountTypes.fromChatName("<img=2>Don Bate"));
		assertEquals(AccountType.ULTIMATE_IRONMAN, AccountTypes.fromChatName("<img=3>Don Bate"));
		assertEquals(AccountType.HARDCORE_IRONMAN, AccountTypes.fromChatName("<img=10>Don Bate"));
		assertEquals(AccountType.GROUP_IRONMAN, AccountTypes.fromChatName("<img=41>Don Bate"));
		assertEquals(AccountType.HARDCORE_GROUP_IRONMAN, AccountTypes.fromChatName("<img=42>Don Bate"));
		assertEquals(AccountType.UNRANKED_GROUP_IRONMAN, AccountTypes.fromChatName("<img=43>Don Bate"));
		assertNull(AccountTypes.fromChatName("Don Bate"));
		assertNull(AccountTypes.fromChatName("<img=99>Don Bate"));
	}

	@Test
	public void skipsUnrecognizedIconsLikeSkulls()
	{
		// PvP menu targets show a skull icon before the account badge
		assertEquals(AccountType.GROUP_IRONMAN, AccountTypes.fromChatName("<img=35><img=41>Swole Max (level-90)"));
		assertEquals(AccountType.IRONMAN, AccountTypes.fromChatName("<col=ffffff><img=99><img=2>Don Bate"));
		assertNull(AccountTypes.fromChatName("<img=35><img=99>Don Bate"));
	}

	@Test
	public void womDecisionLogic()
	{
		// Not on ironman hiscores: unknown (could be main or GIM, never "Main")
		assertNull(AccountTypes.decide(50L, null, null, null));
		// De-ironed: regular exp diverged above ironman exp
		assertNull(AccountTypes.decide(100L, 80L, null, null));
		// Plain ironman
		assertEquals(AccountType.IRONMAN, AccountTypes.decide(80L, 80L, null, null));
		assertEquals(AccountType.IRONMAN, AccountTypes.decide(null, 80L, null, null));
		// Hardcore: hc exp keeps pace with ironman exp
		assertEquals(AccountType.HARDCORE_IRONMAN, AccountTypes.decide(80L, 80L, 80L, null));
		// Dead hardcore: hc exp fell behind, still plain ironman
		assertEquals(AccountType.IRONMAN, AccountTypes.decide(80L, 80L, 40L, null));
		// Ultimate
		assertEquals(AccountType.ULTIMATE_IRONMAN, AccountTypes.decide(80L, 80L, null, 80L));
		assertEquals(AccountType.IRONMAN, AccountTypes.decide(80L, 80L, null, 40L));
	}

	@Test
	public void labels()
	{
		assertEquals("Hardcore Ironman", AccountType.HARDCORE_IRONMAN.label());
		assertEquals("Group Ironman", AccountType.GROUP_IRONMAN.label());
	}
}

