		List<LootDecision.Stack> stacks = Arrays.asList(
			new LootDecision.Stack(21820, 10_000, 150L));

		LootDecision.Notable n = LootDecision.evaluate(stacks, true, MIN);

		assertTrue(n.totalTriggered);
		assertEquals(1_500_000L, n.totalValue);
	}

	@Test
	public void underThresholdIsNull()
	{
		List<LootDecision.Stack> stacks = Arrays.asList(
			new LootDecision.Stack(1, 1, 500L));
		assertNull(LootDecision.evaluate(stacks, false, MIN));
		assertNull(LootDecision.evaluate(stacks, true, MIN));
	}

	@Test
	public void picksHighestValueItemWhenSeveralQualify()
	{
		List<LootDecision.Stack> stacks = Arrays.asList(
			new LootDecision.Stack(1, 1, 1_100_000L),
			new LootDecision.Stack(2, 1, 9_000_000L));

		assertEquals(2, LootDecision.evaluate(stacks, false, MIN).itemId);
	}

	@Test
	public void unitPriceTriggerReportsFullStackValue()
	{
		// 2x an item worth 1.2M each: triggers on unit price, reports stack total
		List<LootDecision.Stack> stacks = Arrays.asList(
			new LootDecision.Stack(1, 2, 1_200_000L));

		LootDecision.Notable n = LootDecision.evaluate(stacks, false, MIN);

		assertEquals(1, n.itemId);
		assertEquals(2, n.quantity);
		assertEquals(2_400_000L, n.itemValue);
		assertFalse(n.totalTriggered);
	}
}

