import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class LootKeyParserTest
{
	@Test
	public void parsesClanBroadcastKill()
	{
		// Wording verified live on 2026-09-02
		LootKeyParser.ClanKill k = LootKeyParser.parseClanKill(
			"Don Bate has defeated IrViMax and received (9,535 coins) worth of loot!");
		assertEquals("Don Bate", k.killer);
		assertEquals("IrViMax", k.victim);
		assertEquals(9_535L, k.value);
	}

	@Test
	public void parsesClanBroadcastWithLargeValue()
	{
		LootKeyParser.ClanKill k = LootKeyParser.parseClanKill(
			"Some Guy has defeated A Victim and received (2,400,000 coins) worth of loot!");
		assertEquals(2_400_000L, k.value);
	}

	@Test
	public void clanBroadcastRejectsOtherLines()
	{
		assertNull(LootKeyParser.parseClanKill("Don Bate has defeated IrViMax."));
		assertNull(LootKeyParser.parseClanKill("You have been defeated by Don Bate."));
		assertNull(LootKeyParser.parseClanKill("Bob received (500 coins) worth of loot!"));
		assertNull(LootKeyParser.parseClanKill(null));
	}

	@Test
	public void parsesValueFromLikelyWordings()
	{
		// Exact official wording is unverified; the parser must be tolerant.
		assertEquals(2_400_000L, LootKeyParser.parseValue(
			"Your loot key is worth approximately 2,400,000 coins.").getAsLong());
		assertEquals(507_000L, LootKeyParser.parseValue(
			"You have received a loot key worth 507,000 coins!").getAsLong());
		assertEquals(1_000_000L, LootKeyParser.parseValue(
			"Loot key value: 1,000,000").getAsLong());
	}

	@Test
