	{
		// The 5-key limit message must not parse "5" as a value
		assertFalse(LootKeyParser.parseValue(
			"You have reached the limit of 5 loot keys.").isPresent());
		assertFalse(LootKeyParser.parseValue(
			"Use it at the Loot Chest in the Ferox Enclave.").isPresent());
		assertFalse(LootKeyParser.parseValue(
			"You open the coffin and find some loot.").isPresent());
	}
}

