package com.github.diogogdias.discordlootboxer;

import static org.junit.Assert.assertEquals;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import javax.imageio.ImageIO;
import org.junit.Test;

public class ScreenshotUtilTest
{
	@Test
	public void upscalesTinyIconsByIntegerNearestScale() throws Exception
	{
		BufferedImage badge = new BufferedImage(13, 13, BufferedImage.TYPE_INT_ARGB);
		badge.setRGB(0, 0, 0xFFFF0000);

		BufferedImage decoded = ImageIO.read(new ByteArrayInputStream(ScreenshotUtil.upscaledIconPng(badge)));

		// 96 / 13 = 7x scale
		assertEquals(91, decoded.getWidth());
		assertEquals(91, decoded.getHeight());
		// Nearest neighbor: the corner source pixel becomes a solid hard-edged block
		assertEquals(0xFFFF0000, decoded.getRGB(0, 0));
		assertEquals(0xFFFF0000, decoded.getRGB(6, 6));
	}

	@Test
	public void encodesPngAtFullResolution() throws Exception
	{
		BufferedImage img = new BufferedImage(320, 200, BufferedImage.TYPE_INT_RGB);
		img.setRGB(10, 10, 0xFF0000);

		byte[] png = ScreenshotUtil.toPng(img);

		BufferedImage decoded = ImageIO.read(new ByteArrayInputStream(png));
		assertEquals(320, decoded.getWidth());
		assertEquals(200, decoded.getHeight());
	}
}

package com.github.diogogdias.discordlootboxer;

import static org.junit.Assert.assertEquals;
import java.util.Locale;
import org.junit.Test;

public class ValueFormatTest
{
	@Test
	public void formatsBillions()
	{
		assertEquals("1.2B", ValueFormat.kmb(1_200_000_000L));
		assertEquals("2B", ValueFormat.kmb(2_000_000_000L));
	}

	@Test
	public void formatsMillions()
	{
		assertEquals("2.4M", ValueFormat.kmb(2_400_000L));
		assertEquals("2M", ValueFormat.kmb(2_000_000L));
		assertEquals("507.9M", ValueFormat.kmb(507_900_000L));
	}

	@Test
	public void formatsThousands()
	{
		assertEquals("209K", ValueFormat.kmb(209_000L));
		assertEquals("1K", ValueFormat.kmb(1_000L));
		assertEquals("999K", ValueFormat.kmb(999_999L));
	}

	@Test
	public void formatsSmallValuesRaw()
	{
		assertEquals("950", ValueFormat.kmb(950L));
		assertEquals("0", ValueFormat.kmb(0L));
	}

	@Test
	public void formatsLocaleIndependently()
	{
		Locale priorDefault = Locale.getDefault();
		try
		{
			Locale.setDefault(Locale.GERMANY);
			assertEquals("2.4M", ValueFormat.kmb(2_400_000L));
		}
		finally
		{
			Locale.setDefault(priorDefault);
		}
	}
